use std::thread;

fn main() {
    let handles: Vec<_> = (0..4)
        .map(|i| thread::spawn(move || {
            println!("thread {i} running");
            i * i
        }))
        .collect();

    for h in handles {
        println!("result: {}", h.join().unwrap());
    }
}
